import base64
import io
import os
from typing import Any, Dict, Optional

import requests


def _image_to_data_url(image: Any) -> str:
    if isinstance(image, str):
        if image.startswith("http://") or image.startswith("https://"):
            resp = requests.get(image, timeout=30)
            resp.raise_for_status()
            mime = resp.headers.get("Content-Type", "image/jpeg")
            b64 = base64.b64encode(resp.content).decode("ascii")
            return f"data:{mime};base64,{b64}"
        if os.path.exists(image):
            with open(image, "rb") as f:
                data = f.read()
            mime = "image/jpeg"
            ext = os.path.splitext(image.lower())[1]
            if ext in {".png"}:
                mime = "image/png"
            elif ext in {".webp"}:
                mime = "image/webp"
            elif ext in {".gif"}:
                mime = "image/gif"
            b64 = base64.b64encode(data).decode("ascii")
            return f"data:{mime};base64,{b64}"
    if isinstance(image, (bytes, bytearray)):
        b64 = base64.b64encode(bytes(image)).decode("ascii")
        return f"data:image/jpeg;base64,{b64}"
    if hasattr(image, "read"):
        data = image.read()
        b64 = base64.b64encode(data).decode("ascii")
        return f"data:image/jpeg;base64,{b64}"
    raise TypeError("Unsupported image input; provide a path, URL, bytes, or file-like object.")


def check_image_for_unsafe_content(image: Any) -> Dict[str, Any]:
    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise EnvironmentError("OPENAI_API_KEY is required.")

    data_url = _image_to_data_url(image)

    url = "https://api.openai.com/v1/responses"
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }
    payload = {
        "model": "gpt-4.1-mini",
        "input": [
            {
                "role": "user",
                "content": [
                    {
                        "type": "input_text",
                        "text": (
                            "Analyze this image for unsafe or policy-sensitive visual content. "
                            "Return JSON with keys: unsafe (boolean), categories (array of strings), "
                            "summary (string), confidence (number from 0 to 1). "
                            "Categories may include nudity, sexual content, graphic violence, self-harm, "
                            "weapons, hate symbols, illegal drugs, exploitative content, or other "
                            "policy-sensitive visual content."
                        ),
                    },
                    {"type": "input_image", "image_url": data_url},
                ],
            }
        ],
        "text": {
            "format": {
                "type": "json_object"
            }
        },
    }

    resp = requests.post(url, headers=headers, json=payload, timeout=60)
    resp.raise_for_status()
    data = resp.json()

    result_text: Optional[str] = None
    for item in data.get("output", []):
        for content in item.get("content", []):
            if content.get("type") in {"output_text", "text"} and content.get("text"):
                result_text = content["text"]
                break
        if result_text:
            break

    if result_text is None:
        return {
            "unsafe": True,
            "categories": ["unknown"],
            "summary": "No analysis text returned from provider.",
            "confidence": 0.0,
            "raw_response": data,
        }

    try:
        import json

        parsed = json.loads(result_text)
        if isinstance(parsed, dict):
            return parsed
    except Exception:
        pass

    return {
        "unsafe": True,
        "categories": ["unknown"],
        "summary": result_text,
        "confidence": 0.0,
        "raw_response": data,
    }
